#!/usr/bin/env node

/**
 * Send a Slack message via the Web API (chat.postMessage).
 *
 * Usage:
 *   SLACK_TOKEN=xoxb-... node send_message.cjs <channel> <text> [options]
 *
 * Options:
 *   --thread-ts <ts>      Reply inside an existing thread
 *   --username <name>     Override bot display name (requires chat:write.customize)
 *   --icon-emoji <emoji>  Override bot icon (requires chat:write.customize)
 *
 * <channel> may be "#name" or a channel ID (C...).
 * Prints "Success: ..." with the message timestamp, or "Failure: ..." and exits 1.
 */

const API = 'https://slack.com/api/chat.postMessage';

function parseArgs(argv) {
  const opts = { thread_ts: null, username: null, icon_emoji: null };
  const positional = [];
  for (let i = 0; i < argv.length; i++) {
    const arg = argv[i];
    if (arg === '--thread-ts' || arg === '--username' || arg === '--icon-emoji') {
      opts[arg.slice(2)] = argv[++i];
    } else if (arg.startsWith('--')) {
      opts[arg.slice(2)] = argv[++i];
    } else {
      positional.push(arg);
    }
  }
  return { opts, positional };
}

async function main() {
  const token = process.env.SLACK_TOKEN;
  if (!token) {
    process.stderr.write('Failure: SLACK_TOKEN environment variable is required.\n');
    process.exit(1);
  }

  const { opts, positional } = parseArgs(process.argv.slice(2));
  if (positional.length < 2) {
    process.stderr.write(
      'Usage: SLACK_TOKEN=xoxb-... node send_message.cjs <channel> <text> [--thread-ts <ts>] [--username <name>] [--icon-emoji <emoji>]\n',
    );
    process.exit(1);
  }

  const payload = {
    channel: positional[0],
    text: positional.slice(1).join(' '),
  };
  for (const key of ['thread_ts', 'username', 'icon_emoji']) {
    if (opts[key]) payload[key] = opts[key];
  }

  try {
    const res = await fetch(API, {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${token}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(payload),
    });
    const data = await res.json();
    if (!data.ok) {
      process.stderr.write(`Failure: Slack API error: ${data.error}\n`);
      process.exit(1);
    }
    const permalink = data.message && data.message.permalink;
    process.stdout.write(
      `Success: Sent message to ${payload.channel} (ts=${data.ts}, permalink=${permalink || 'n/a'})\n`,
    );
  } catch (err) {
    process.stderr.write(`Failure: ${err.message}\n`);
    process.exit(1);
  }
}

main();

#!/usr/bin/env node

/**
 * List Slack channels via the Web API (conversations.list).
 *
 * Usage:
 *   SLACK_TOKEN=xoxb-... node list_channels.cjs [--types <types>] [--limit <n>] [--cursor <cursor>]
 *
 * Options:
 *   --types <types>   Comma-separated: public_channel,private_channel,mpim,im (default: public_channel,private_channel)
 *   --limit <n>       Results per page, 1-200 (default: 100)
 *   --cursor <cursor> Cursor from a previous response's next_cursor to fetch the next page
 *
 * Prints a truncated table plus next_cursor when more results exist.
 */

const API = 'https://slack.com/api/conversations.list';

function parseArgs(argv) {
  const opts = { types: 'public_channel,private_channel', limit: 100, cursor: null };
  for (let i = 0; i < argv.length; i++) {
    const arg = argv[i];
    if (arg === '--types' || arg === '--limit' || arg === '--cursor') {
      opts[arg.slice(2)] = argv[++i];
    }
  }
  const parsed = parseInt(opts.limit, 10);
  if (Number.isNaN(parsed) || parsed < 1 || parsed > 200) opts.limit = 200;
  else opts.limit = parsed;
  return opts;
}

async function main() {
  const token = process.env.SLACK_TOKEN;
  if (!token) {
    process.stderr.write('Failure: SLACK_TOKEN environment variable is required.\n');
    process.exit(1);
  }

  const opts = parseArgs(process.argv.slice(2));
  const params = new URLSearchParams({ types: opts.types, limit: String(opts.limit) });
  if (opts.cursor) params.set('cursor', opts.cursor);

  try {
    const res = await fetch(`${API}?${params.toString()}`, {
      headers: { Authorization: `Bearer ${token}` },
    });
    const data = await res.json();
    if (!data.ok) {
      process.stderr.write(`Failure: Slack API error: ${data.error}\n`);
      process.exit(1);
    }

    const channels = data.channels || [];
    const lines = channels.map((c) => {
      const name = c.is_archived ? `${c.name} (archived)` : c.name;
      return `${c.id}\t${c.is_private ? 'private' : 'public'}\t${c.num_members ?? '?'}\t#${name}`;
    });

    const header = 'ID\tTYPE\tMEMBERS\tNAME';
    const shown = lines.slice(0, 50);
    const out = [header, ...shown];
    if (lines.length > shown.length) {
      out.push(`... and ${lines.length - shown.length} more channels`);
    }
    const next = data.response_metadata && data.response_metadata.next_cursor;
    if (next) out.push(`next_cursor: ${next}`);
    out.push(`total_channels_returned: ${lines.length}`);
    process.stdout.write(`${out.join('\n')}\n`);
  } catch (err) {
    process.stderr.write(`Failure: ${err.message}\n`);
    process.exit(1);
  }
}

main();

